=== FILE: rtl/axil_timer.v ===
`timescale 1ns/1ps
// axil_timer: AXI4-Lite timer peripheral with level interrupt.
// Implements microarchitecture_spec.md (axil_timer) sections 1-9.
// Single clock (aclk), synchronous active-low reset (aresetn).
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State inventory (uarch section 2)
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [31:0]           rdata_q;
    reg                  en_q;
    reg                  ie_q;
    reg                  mode_q;
    reg [31:0]           load_q;
    reg [31:0]           count_q;
    reg                  expired_q;

    // ------------------------------------------------------------------
    // Ready outputs (uarch 4.1): from flops only
    // ------------------------------------------------------------------
    assign s_axil_awready = ~aw_held_q & ~bvalid_q;
    assign s_axil_wready  = ~w_held_q  & ~bvalid_q;
    assign s_axil_arready = ~rvalid_q;

    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

    // ------------------------------------------------------------------
    // Handshake terms (uarch 4.2)
    // ------------------------------------------------------------------
    wire aw_hs   = s_axil_awvalid & s_axil_awready;
    wire w_hs    = s_axil_wvalid  & s_axil_wready;
    wire ar_hs   = s_axil_arvalid & s_axil_arready;
    wire wr_done = (aw_held_q | aw_hs) & (w_held_q | w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held_q  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held_q  ? w_strb_q  : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode (uarch 5)
    // ------------------------------------------------------------------
    wire wr_upper_zero;
    wire rd_upper_zero;
    generate
        if (ADDR_WIDTH > 4) begin : g_wide_addr
            assign wr_upper_zero = ~|wr_addr[ADDR_WIDTH-1:4];
            assign rd_upper_zero = ~|s_axil_araddr[ADDR_WIDTH-1:4];
        end else begin : g_narrow_addr
            assign wr_upper_zero = 1'b1;
            assign rd_upper_zero = 1'b1;
        end
    endgenerate

    wire       wr_hit = (wr_addr[1:0] == 2'b00) & wr_upper_zero;
    wire [1:0] wr_idx = wr_addr[3:2];
    wire       rd_hit = (s_axil_araddr[1:0] == 2'b00) & rd_upper_zero;
    wire [1:0] rd_idx = s_axil_araddr[3:2];

    // ------------------------------------------------------------------
    // Write datapath (uarch 6)
    // ------------------------------------------------------------------
    wire wr_ctrl = wr_done & wr_hit & (wr_idx == 2'd0) & wr_strb[0];
    wire wr_load = wr_done & wr_hit & (wr_idx == 2'd1);
    wire wr_clr  = wr_done & wr_hit & (wr_idx == 2'd3) & wr_strb[0] & wr_data[0];
    wire wr_err  = ~wr_hit | (wr_idx == 2'd2);

    wire [31:0] load_mask = {{8{wr_strb[3]}}, {8{wr_strb[2]}},
                             {8{wr_strb[1]}}, {8{wr_strb[0]}}};
    wire [31:0] load_d    = wr_load ? ((load_q & ~load_mask) | (wr_data & load_mask))
                                    : load_q;

    // ------------------------------------------------------------------
    // Read mux (uarch 7): values before the accepting edge
    // ------------------------------------------------------------------
    wire [31:0] rd_reg_val = (rd_idx == 2'd0) ? {29'd0, mode_q, ie_q, en_q} :
                             (rd_idx == 2'd1) ? load_q :
                             (rd_idx == 2'd2) ? count_q :
                                                {31'd0, expired_q};
    wire [31:0] rd_mux     = rd_hit ? rd_reg_val : 32'd0;

    // ------------------------------------------------------------------
    // Counter / CTRL next state (uarch 8)
    // ------------------------------------------------------------------
    wire        end_edge  = en_q & (count_q[31:1] == 31'd0);
    wire        start     = wr_ctrl &  wr_data[0];
    wire        stop      = wr_ctrl & ~wr_data[0];
    wire [31:0] count_dec = count_q - 32'd1;
    wire [31:0] end_value = mode_q ? load_q : 32'd0;

    reg        en_d;
    reg        ie_d;
    reg        mode_d;
    reg [31:0] count_d;

    always @(*) begin
        en_d    = en_q;
        ie_d    = ie_q;
        mode_d  = mode_q;
        count_d = count_q;
        if (wr_ctrl) begin
            ie_d   = wr_data[1];
            mode_d = wr_data[2];
        end
        if (start) begin
            // row 1: start / restart (also CTRL-wins with EN=1)
            en_d    = 1'b1;
            count_d = load_q;
        end else if (stop) begin
            en_d = 1'b0;
            if (end_edge) begin
                count_d = end_value;      // row 2: CTRL-wins with EN=0
            end else if (en_q) begin
                count_d = count_dec;      // row 3: stop edge still decrements
            end else begin
                count_d = count_q;        // row 4: already stopped
            end
        end else if (end_edge) begin
            if (mode_q) begin
                en_d    = 1'b1;           // row 6: periodic reload (old LOAD)
                count_d = load_q;
            end else begin
                en_d    = 1'b0;           // row 5: one-shot end
                count_d = 32'd0;
            end
        end else if (en_q) begin
            count_d = count_dec;          // row 7
        end
    end

    // ------------------------------------------------------------------
    // Sequential logic
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held_q  <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rresp_q   <= RESP_OKAY;
            rdata_q   <= 32'd0;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
            expired_q <= 1'b0;
        end else begin
            // AW hold (uarch 4.3)
            if (wr_done) begin
                aw_held_q <= 1'b0;
            end else if (aw_hs) begin
                aw_held_q <= 1'b1;
            end
            if (aw_hs && !wr_done) begin
                aw_addr_q <= s_axil_awaddr;
            end

            // W hold (uarch 4.3)
            if (wr_done) begin
                w_held_q <= 1'b0;
            end else if (w_hs) begin
                w_held_q <= 1'b1;
            end
            if (w_hs && !wr_done) begin
                w_data_q <= s_axil_wdata;
                w_strb_q <= s_axil_wstrb;
            end

            // B channel (uarch 4.4)
            if (wr_done) begin
                bvalid_q <= 1'b1;
                bresp_q  <= wr_err ? RESP_SLVERR : RESP_OKAY;
            end else if (s_axil_bready) begin
                bvalid_q <= 1'b0;
            end

            // R channel (uarch 4.5)
            if (ar_hs) begin
                rvalid_q <= 1'b1;
                rdata_q  <= rd_mux;
                rresp_q  <= rd_hit ? RESP_OKAY : RESP_SLVERR;
            end else if (s_axil_rready) begin
                rvalid_q <= 1'b0;
            end

            // Registers and counter (uarch 6, 8)
            en_q    <= en_d;
            ie_q    <= ie_d;
            mode_q  <= mode_d;
            count_q <= count_d;
            load_q  <= load_d;

            // EXPIRED (uarch 8.4): end edge beats clear
            if (end_edge) begin
                expired_q <= 1'b1;
            end else if (wr_clr) begin
                expired_q <= 1'b0;
            end
        end
    end

    // Interrupt (uarch 9)
    assign irq = expired_q & ie_q;

    // ------------------------------------------------------------------
    // Design-intent assertions (formal only; not compiled otherwise)
    // ------------------------------------------------------------------
`ifdef FORMAL
    always @(*) begin
        // At most one half of a write is ever held.
        assert (!(aw_held_q && w_held_q));
        // No write is held while its response is pending.
        if (bvalid_q) assert (!aw_held_q && !w_held_q);
        // Only OKAY and SLVERR are produced.
        assert (bresp_q == RESP_OKAY || bresp_q == RESP_SLVERR);
        assert (rresp_q == RESP_OKAY || rresp_q == RESP_SLVERR);
        // Unmapped reads return zero data.
        if (rresp_q == RESP_SLVERR) assert (rdata_q == 32'd0);
        // irq is exactly EXPIRED AND IE.
        assert (irq == (expired_q & ie_q));
    end
`endif

endmodule
=== END FILE ===
=== FILE: tb/tb_axil_timer.v ===
`timescale 1ns/1ps
// Self-checking testbench for axil_timer.
// Instantiates the block at ADDR_WIDTH=4 and ADDR_WIDTH=8 and runs the same
// suite on each (sel selects which DUT the bus tasks drive).
module tb_axil_timer;

    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;
    localparam [1:0] OKAY     = 2'b00;
    localparam [1:0] SLVERR   = 2'b10;

    reg        clk;
    reg        aresetn;
    reg        sel;
    reg  [7:0] awaddr;
    reg [31:0] wdata;
    reg  [3:0] wstrb;
    reg        awvalid;
    reg        wvalid;
    reg        bready;
    reg  [7:0] araddr;
    reg        arvalid;
    reg        rready;

    integer cyc;
    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;
    reg [8*64-1:0] ctx;

    reg  [1:0] last_bresp;
    reg [31:0] last_rdata;
    reg  [1:0] last_rresp;
    integer    wr_edge;
    integer    rd_edge;
    reg        irq_before_done;
    reg        irq_at_done;

    // DUT outputs
    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire  [1:0] bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire  [1:0] bresp8, rresp8;
    wire [31:0] rdata8;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr[3:0]),
        .s_axil_awvalid (awvalid & ~sel),
        .s_axil_awready (awready4),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid & ~sel),
        .s_axil_wready  (wready4),
        .s_axil_bresp   (bresp4),
        .s_axil_bvalid  (bvalid4),
        .s_axil_bready  (bready & ~sel),
        .s_axil_araddr  (araddr[3:0]),
        .s_axil_arvalid (arvalid & ~sel),
        .s_axil_arready (arready4),
        .s_axil_rdata   (rdata4),
        .s_axil_rresp   (rresp4),
        .s_axil_rvalid  (rvalid4),
        .s_axil_rready  (rready & ~sel),
        .irq            (irq4)
    );

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid & sel),
        .s_axil_awready (awready8),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid & sel),
        .s_axil_wready  (wready8),
        .s_axil_bresp   (bresp8),
        .s_axil_bvalid  (bvalid8),
        .s_axil_bready  (bready & sel),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid & sel),
        .s_axil_arready (arready8),
        .s_axil_rdata   (rdata8),
        .s_axil_rresp   (rresp8),
        .s_axil_rvalid  (rvalid8),
        .s_axil_rready  (rready & sel),
        .irq            (irq8)
    );

    wire        cur_awready = sel ? awready8 : awready4;
    wire        cur_wready  = sel ? wready8  : wready4;
    wire        cur_bvalid  = sel ? bvalid8  : bvalid4;
    wire  [1:0] cur_bresp   = sel ? bresp8   : bresp4;
    wire        cur_arready = sel ? arready8 : arready4;
    wire        cur_rvalid  = sel ? rvalid8  : rvalid4;
    wire  [1:0] cur_rresp   = sel ? rresp8   : rresp4;
    wire [31:0] cur_rdata   = sel ? rdata8   : rdata4;
    wire        cur_irq     = sel ? irq8     : irq4;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // cyc == E when sampled #1 after edge number E
    always @(posedge clk) cyc <= cyc + 1;

    // ------------------------------------------------------------------
    // Checking helpers
    // ------------------------------------------------------------------
    task check(input cond, input [8*64-1:0] msg);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL [%0s] sel=%0d cyc=%0d: %0s", ctx, sel, cyc, msg);
            end
        end
    endtask

    task check32(input [31:0] got, input [31:0] exp, input [8*64-1:0] msg);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL [%0s] sel=%0d cyc=%0d: %0s got %h expected %h",
                       ctx, sel, cyc, msg, got, exp);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks. All are entered and left at #1 after a clock edge.
    // ------------------------------------------------------------------
    task do_write(input [7:0] addr, input [31:0] data, input [3:0] strb,
                  input integer aw_dly, input integer w_dly, input integer b_dly);
        integer n;
        reg aw_pend, w_pend, aw_acc, w_acc, b_acc;
        reg [1:0] resp0;
        begin
            awaddr  = addr;
            wdata   = data;
            wstrb   = strb;
            aw_pend = 1'b1;
            w_pend  = 1'b1;
            n       = 0;
            awvalid = (aw_dly == 0);
            wvalid  = (w_dly == 0);
            bready  = (b_dly == 0);
            while ((aw_pend || w_pend) && n < 64) begin
                aw_acc = awvalid & cur_awready;
                w_acc  = wvalid & cur_wready;
                irq_before_done = cur_irq;
                check(cur_bvalid == 1'b0, "bvalid low before write completes");
                @(posedge clk); #1;
                n = n + 1;
                if (aw_acc) begin aw_pend = 1'b0; awvalid = 1'b0; end
                if (w_acc)  begin w_pend  = 1'b0; wvalid  = 1'b0; end
                if (!aw_pend && w_pend) check(cur_awready == 1'b0, "awready low while AW held");
                if (!w_pend && aw_pend) check(cur_wready == 1'b0, "wready low while W held");
                if (aw_pend && n >= aw_dly) awvalid = 1'b1;
                if (w_pend && n >= w_dly)   wvalid  = 1'b1;
            end
            if (aw_pend || w_pend) check(1'b0, "write handshake timeout");
            awvalid     = 1'b0;
            wvalid      = 1'b0;
            wr_edge     = cyc;
            irq_at_done = cur_irq;
            check(cur_bvalid == 1'b1, "bvalid high after completing edge");
            check(cur_awready == 1'b0 && cur_wready == 1'b0, "aw/wready low while bvalid");
            resp0      = cur_bresp;
            last_bresp = cur_bresp;
            n     = 0;
            b_acc = 1'b0;
            while (!b_acc && n < 64) begin
                if (n >= b_dly) bready = 1'b1;
                b_acc = cur_bvalid & bready;
                @(posedge clk); #1;
                n = n + 1;
                if (!b_acc) begin
                    check(cur_bvalid == 1'b1, "bvalid held until bready");
                    check(cur_bresp == resp0, "bresp stable while waiting");
                    check(cur_awready == 1'b0 && cur_wready == 1'b0, "no write accepted while bvalid");
                end
            end
            bready = 1'b0;
            check(cur_bvalid == 1'b0, "bvalid low after B handshake");
        end
    endtask

    task do_read(input [7:0] addr, input integer r_dly);
        integer n;
        reg ar_pend, ar_acc, r_acc;
        begin
            araddr  = addr;
            arvalid = 1'b1;
            rready  = (r_dly == 0);
            ar_pend = 1'b1;
            n       = 0;
            while (ar_pend && n < 64) begin
                ar_acc = arvalid & cur_arready;
                check(cur_rvalid == 1'b0, "rvalid low before AR accepted");
                @(posedge clk); #1;
                n = n + 1;
                if (ar_acc) begin ar_pend = 1'b0; arvalid = 1'b0; end
            end
            if (ar_pend) check(1'b0, "read handshake timeout");
            arvalid = 1'b0;
            rd_edge = cyc;
            check(cur_rvalid == 1'b1, "rvalid high after AR accepting edge");
            check(cur_arready == 1'b0, "arready low while rvalid");
            last_rdata = cur_rdata;
            last_rresp = cur_rresp;
            n     = 0;
            r_acc = 1'b0;
            while (!r_acc && n < 64) begin
                if (n >= r_dly) rready = 1'b1;
                r_acc = cur_rvalid & rready;
                @(posedge clk); #1;
                n = n + 1;
                if (!r_acc) begin
                    check(cur_rvalid == 1'b1, "rvalid held until rready");
                    check32(cur_rdata, last_rdata, "rdata stable while waiting");
                    check(cur_rresp == last_rresp, "rresp stable while waiting");
                end
            end
            rready = 1'b0;
            check(cur_rvalid == 1'b0, "rvalid low after R handshake");
        end
    endtask

    task wr(input [7:0] a, input [31:0] d, input [3:0] s, input [1:0] exp_resp);
        begin
            do_write(a, d, s, 0, 0, 0);
            check(last_bresp == exp_resp, "write response code");
        end
    endtask

    task rd(input [7:0] a, input [31:0] exp, input [1:0] exp_resp);
        begin
            do_read(a, 0);
            check32(last_rdata, exp, "read data");
            check(last_rresp == exp_resp, "read response code");
        end
    endtask

    task clear_status;
        begin
            wr(A_STATUS, 32'h1, 4'hF, OKAY);
        end
    endtask

    task wait_until(input integer target);
        begin
            while (cyc < target) begin
                @(posedge clk); #1;
            end
            check(cyc == target, "wait target reached on time");
        end
    endtask

    task idle_low_until(input integer target);
        begin
            while (cyc < target) begin
                check(cur_irq == 1'b0, "irq low before end edge");
                @(posedge clk); #1;
            end
            check(cyc == target, "reference edge reached on time");
        end
    endtask

    task irq_low_until(input integer target);
        begin
            idle_low_until(target);
            check(cur_irq == 1'b1, "irq high after end edge");
        end
    endtask

    // ------------------------------------------------------------------
    // Test suite (run once per DUT)
    // ------------------------------------------------------------------
    task run_suite;
        integer E, E2, S, k, R, i;
        begin
            // Reset values
            ctx = "reset values";
            check(cur_awready == 1'b1 && cur_wready == 1'b1 && cur_arready == 1'b1, "readies high after reset");
            check(cur_bvalid == 1'b0 && cur_rvalid == 1'b0 && cur_irq == 1'b0, "valids and irq low after reset");
            rd(A_CTRL,   32'h0, OKAY);
            rd(A_LOAD,   32'h0, OKAY);
            rd(A_COUNT,  32'h0, OKAY);
            rd(A_STATUS, 32'h0, OKAY);

            // LOAD with strobes
            ctx = "LOAD strobes";
            wr(A_LOAD, 32'h11223344, 4'hF,    OKAY); rd(A_LOAD, 32'h11223344, OKAY);
            wr(A_LOAD, 32'hAABBCCDD, 4'b0101, OKAY); rd(A_LOAD, 32'h11BB33DD, OKAY);
            wr(A_LOAD, 32'hFFFFFFFF, 4'b0000, OKAY); rd(A_LOAD, 32'h11BB33DD, OKAY);
            wr(A_LOAD, 32'h99000000, 4'b1000, OKAY); rd(A_LOAD, 32'h99BB33DD, OKAY);

            // CTRL fields and wstrb[0]
            ctx = "CTRL";
            wr(A_CTRL, 32'hFFFFFFF6, 4'hF,    OKAY); rd(A_CTRL, 32'h6, OKAY);
            wr(A_CTRL, 32'h00000001, 4'b1110, OKAY); rd(A_CTRL, 32'h6, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            wr(A_CTRL, 32'h0, 4'hF, OKAY); rd(A_CTRL, 32'h0, OKAY);
            wr(A_STATUS, 32'hFFFFFFFF, 4'hF, OKAY); rd(A_STATUS, 32'h0, OKAY);

            // Decode: COUNT, unaligned, unmapped
            ctx = "decode";
            wr(A_LOAD, 32'hDEADBEEF, 4'hF, OKAY);
            wr(A_COUNT, 32'h12345678, 4'hF, SLVERR);
            rd(A_COUNT, 32'h0, OKAY);
            for (i = 0; i < 16; i = i + 1) begin
                if (i[1:0] != 2'b00) rd(i[7:0], 32'h0, SLVERR);
            end
            wr(8'h05, 32'h0, 4'hF, SLVERR);
            wr(8'h01, 32'h7, 4'hF, SLVERR);
            wr(8'h0E, 32'h1, 4'hF, SLVERR);
            rd(A_LOAD,   32'hDEADBEEF, OKAY);
            rd(A_CTRL,   32'h0, OKAY);
            rd(A_STATUS, 32'h0, OKAY);
            rd(A_COUNT,  32'h0, OKAY);
            if (sel) begin
                ctx = "decode wide";
                wr(A_CTRL, 32'h6, 4'hF, OKAY);
                for (i = 1; i < 16; i = i + 1) begin
                    rd({i[3:0], 4'h0}, 32'h0, SLVERR);
                    rd({i[3:0], 4'h4}, 32'h0, SLVERR);
                end
                rd(8'hFF, 32'h0, SLVERR);
                wr(8'h10, 32'h1, 4'hF, SLVERR);
                wr(8'h1C, 32'h1, 4'hF, SLVERR);
                wr(8'h94, 32'h0, 4'hF, SLVERR);
                rd(A_CTRL,  32'h6, OKAY);
                rd(A_LOAD,  32'hDEADBEEF, OKAY);
                rd(A_COUNT, 32'h0, OKAY);
                wr(A_CTRL, 32'h0, 4'hF, OKAY);
            end

            // Channel ordering and backpressure
            ctx = "ordering";
            do_write(A_LOAD, 32'h01010101, 4'hF, 0, 3, 0);
            check(last_bresp == OKAY, "AW-first bresp"); rd(A_LOAD, 32'h01010101, OKAY);
            do_write(A_LOAD, 32'h02020202, 4'hF, 3, 0, 0);
            check(last_bresp == OKAY, "W-first bresp");  rd(A_LOAD, 32'h02020202, OKAY);
            do_write(A_LOAD, 32'h03030303, 4'hF, 2, 2, 0);
            check(last_bresp == OKAY, "together bresp"); rd(A_LOAD, 32'h03030303, OKAY);
            do_write(A_LOAD, 32'h04040404, 4'hF, 0, 0, 4);
            check(last_bresp == OKAY, "B backpressure bresp"); rd(A_LOAD, 32'h04040404, OKAY);
            do_write(A_COUNT, 32'h0, 4'hF, 1, 0, 3);
            check(last_bresp == SLVERR, "SLVERR held under backpressure");
            do_read(A_LOAD, 5);
            check32(last_rdata, 32'h04040404, "R backpressure data");
            check(last_rresp == OKAY, "R backpressure resp");
            do_read(8'h03, 3);
            check32(last_rdata, 32'h0, "unmapped R backpressure data");
            check(last_rresp == SLVERR, "unmapped R backpressure resp");

            // One-shot N=8
            ctx = "oneshot N=8";
            wr(A_LOAD, 32'd8, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h3, 4'hF, OKAY);
            E = wr_edge;
            check(irq_at_done == 1'b0, "irq low after start edge");
            do_read(A_COUNT, 0);
            k = rd_edge - 1 - E;
            check(k >= 0 && k < 8, "COUNT read inside count");
            check32(last_rdata, 8 - k, "COUNT = N-k");
            irq_low_until(E + 8);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_CTRL, 32'h2, OKAY);
            rd(A_STATUS, 32'h1, OKAY);
            wr(A_STATUS, 32'h1, 4'hF, OKAY);
            check(irq_before_done == 1'b1, "irq high before clear");
            check(irq_at_done == 1'b0, "irq low right after clear edge");
            rd(A_STATUS, 32'h0, OKAY);
            rd(A_COUNT, 32'h0, OKAY);

            // One-shot N=1
            ctx = "oneshot N=1";
            wr(A_LOAD, 32'd1, 4'hF, OKAY);
            wr(A_CTRL, 32'h3, 4'hF, OKAY);
            E = wr_edge;
            check(irq_at_done == 1'b0, "irq low after start edge");
            irq_low_until(E + 1);
            rd(A_COUNT, 32'h0, OKAY);
            clear_status;

            // Periodic N=4, then stop
            ctx = "periodic N=4";
            wr(A_LOAD, 32'd4, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E = wr_edge;
            irq_low_until(E + 4);
            wr(A_STATUS, 32'h1, 4'hF, OKAY);
            check(((wr_edge - E) % 4) != 0, "clear not on an end edge");
            check(irq_at_done == 1'b0, "irq low after clear");
            irq_low_until(E + 8);
            do_read(A_COUNT, 0);
            k = rd_edge - 1 - E;
            check32(last_rdata, 4 - (k % 4), "periodic COUNT");
            rd(A_CTRL, 32'h7, OKAY);
            rd(A_STATUS, 32'h1, OKAY);
            ctx = "periodic stop";
            wr(A_CTRL, 32'h6, 4'hF, OKAY);
            S = wr_edge;
            k = S - E;
            rd(A_COUNT, 4 - (k % 4), OKAY);
            clear_status;
            wait_until(cyc + 12);
            rd(A_STATUS, 32'h0, OKAY);
            rd(A_COUNT, 4 - (k % 4), OKAY);
            rd(A_CTRL, 32'h6, OKAY);
            wr(A_CTRL, 32'h6, 4'hF, OKAY);
            rd(A_COUNT, 4 - (k % 4), OKAY);

            // LOAD = 0, one-shot and periodic
            ctx = "load0 oneshot";
            wr(A_LOAD, 32'd0, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h3, 4'hF, OKAY);
            E = wr_edge;
            check(irq_at_done == 1'b0, "irq low after start edge");
            irq_low_until(E + 1);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_CTRL, 32'h2, OKAY);
            clear_status;
            rd(A_STATUS, 32'h0, OKAY);
            ctx = "load0 periodic";
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E = wr_edge;
            check(irq_at_done == 1'b0, "irq low after start edge");
            irq_low_until(E + 1);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_CTRL, 32'h7, OKAY);
            wr(A_STATUS, 32'h1, 4'hF, OKAY);
            check(irq_at_done == 1'b1, "end edge beats clear every edge");
            rd(A_STATUS, 32'h1, OKAY);
            wr(A_CTRL, 32'h2, 4'hF, OKAY);
            rd(A_CTRL, 32'h2, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_STATUS, 32'h1, OKAY);
            clear_status;
            rd(A_STATUS, 32'h0, OKAY);

            // CTRL wins: restart on end edge
            ctx = "restart on end edge";
            wr(A_LOAD, 32'd10, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h3, 4'hF, OKAY);
            E = wr_edge;
            idle_low_until(E + 9);
            wr(A_CTRL, 32'h3, 4'hF, OKAY);
            check(wr_edge == E + 10, "restart write lands on end edge");
            check(irq_before_done == 1'b0, "irq low before end edge");
            check(irq_at_done == 1'b1, "EXPIRED set on restart end edge");
            E2 = wr_edge;
            do_read(A_COUNT, 0);
            k = rd_edge - 1 - E2;
            check32(last_rdata, 10 - k, "restarted COUNT");
            rd(A_CTRL, 32'h3, OKAY);
            clear_status;
            irq_low_until(E2 + 10);
            rd(A_CTRL, 32'h2, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            clear_status;

            // CTRL wins: stop on end edge (periodic, then one-shot)
            ctx = "stop on end edge periodic";
            wr(A_LOAD, 32'd5, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E = wr_edge;
            idle_low_until(E + 4);
            wr(A_CTRL, 32'h2, 4'hF, OKAY);
            check(wr_edge == E + 5, "stop write lands on end edge");
            check(irq_at_done == 1'b1, "EXPIRED set on stop end edge");
            rd(A_CTRL, 32'h2, OKAY);
            rd(A_COUNT, 32'd5, OKAY);
            rd(A_STATUS, 32'h1, OKAY);
            wait_until(cyc + 15);
            rd(A_COUNT, 32'd5, OKAY);
            clear_status;
            rd(A_STATUS, 32'h0, OKAY);
            ctx = "stop on end edge oneshot";
            wr(A_CTRL, 32'h3, 4'hF, OKAY);
            E = wr_edge;
            idle_low_until(E + 4);
            wr(A_CTRL, 32'h2, 4'hF, OKAY);
            check(wr_edge == E + 5, "stop write lands on end edge");
            rd(A_CTRL, 32'h2, OKAY);
            rd(A_COUNT, 32'h0, OKAY);
            rd(A_STATUS, 32'h1, OKAY);
            clear_status;

            // End beats clear
            ctx = "end beats clear";
            wr(A_LOAD, 32'd6, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E = wr_edge;
            irq_low_until(E + 6);
            wait_until(E + 11);
            wr(A_STATUS, 32'h1, 4'hF, OKAY);
            check(wr_edge == E + 12, "clear lands on end edge");
            check(irq_at_done == 1'b1, "EXPIRED stays set");
            rd(A_STATUS, 32'h1, OKAY);
            wr(A_STATUS, 32'h1, 4'hF, OKAY);
            check(((wr_edge - E) % 6) != 0, "second clear off end edge");
            check(irq_at_done == 1'b0, "clear off end edge works");
            rd(A_STATUS, 32'h0, OKAY);
            wr(A_CTRL, 32'h0, 4'hF, OKAY);
            clear_status;

            // LOAD write on a periodic end edge: old or new value allowed
            ctx = "load on end edge";
            wr(A_LOAD, 32'd6, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E = wr_edge;
            idle_low_until(E + 5);
            wr(A_LOAD, 32'd9, 4'hF, OKAY);
            check(wr_edge == E + 6, "LOAD write lands on end edge");
            E2 = wr_edge;
            do_read(A_COUNT, 0);
            k = rd_edge - 1 - E2;
            if (last_rdata == 6 - k)      R = 6;
            else if (last_rdata == 9 - k) R = 9;
            else                          R = 0;
            check(R != 0, "reload uses old or new LOAD");
            if (R == 0) R = 6;
            clear_status;
            irq_low_until(E2 + R);
            clear_status;
            irq_low_until(E2 + R + 9);
            wr(A_CTRL, 32'h0, 4'hF, OKAY);
            clear_status;

            // Transfers that do not disturb a count; restart mid-count
            ctx = "undisturbed";
            wr(A_LOAD, 32'd20, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E = wr_edge;
            wr(A_COUNT, 32'h0, 4'hF, SLVERR);
            wr(8'h01, 32'h1, 4'hF, SLVERR);
            wr(A_STATUS, 32'h0, 4'hF, OKAY);
            wr(A_STATUS, 32'h1, 4'b1110, OKAY);
            wr(A_CTRL, 32'h0, 4'b1110, OKAY);
            if (sel) wr(8'h20, 32'h0, 4'hF, SLVERR);
            rd(A_CTRL, 32'h7, OKAY);
            irq_low_until(E + 20);
            ctx = "restart mid-count";
            clear_status;
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E2 = wr_edge;
            irq_low_until(E2 + 20);
            wr(A_CTRL, 32'h0, 4'hF, OKAY);

            // irq follows IE with no delay
            ctx = "irq vs IE";
            rd(A_STATUS, 32'h1, OKAY);
            check(cur_irq == 1'b0, "irq low with IE=0");
            wr(A_CTRL, 32'h2, 4'hF, OKAY);
            check(irq_before_done == 1'b0, "irq low before IE set");
            check(irq_at_done == 1'b1, "irq high right after IE set");
            wr(A_CTRL, 32'h0, 4'hF, OKAY);
            check(irq_before_done == 1'b1, "irq high before IE clear");
            check(irq_at_done == 1'b0, "irq low right after IE clear");
            clear_status;
            rd(A_STATUS, 32'h0, OKAY);

            // Reset in the middle of a write
            ctx = "reset mid-write";
            awaddr  = A_LOAD;
            awvalid = 1'b1;
            check(cur_awready == 1'b1, "awready high before AW");
            @(posedge clk); #1;
            awvalid = 1'b0;
            check(cur_awready == 1'b0, "AW held");
            check(cur_wready == 1'b1, "wready high while AW held");
            aresetn = 1'b0;
            @(posedge clk); #1;
            aresetn = 1'b1;
            check(cur_awready == 1'b1 && cur_wready == 1'b1, "readies high after reset");
            check(cur_bvalid == 1'b0 && cur_rvalid == 1'b0, "valids low after reset");
            wdata  = 32'h55AA55AA;
            wstrb  = 4'hF;
            wvalid = 1'b1;
            @(posedge clk); #1;
            wvalid = 1'b0;
            check(cur_wready == 1'b0, "W held after reset");
            check(cur_bvalid == 1'b0, "no completion from pre-reset AW");
            for (i = 0; i < 3; i = i + 1) begin
                @(posedge clk); #1;
                check(cur_bvalid == 1'b0, "bvalid stays low with W only");
            end
            awaddr  = A_LOAD;
            awvalid = 1'b1;
            @(posedge clk); #1;
            awvalid = 1'b0;
            check(cur_bvalid == 1'b1, "write completes with AW");
            check(cur_bresp == OKAY, "bresp OKAY");
            bready = 1'b1;
            @(posedge clk); #1;
            bready = 1'b0;
            check(cur_bvalid == 1'b0, "bvalid low after handshake");
            rd(A_LOAD, 32'h55AA55AA, OKAY);

            // Reset with a running count and a pending read
            ctx = "reset running";
            wr(A_LOAD, 32'd3, 4'hF, OKAY);
            clear_status;
            wr(A_CTRL, 32'h7, 4'hF, OKAY);
            E = wr_edge;
            irq_low_until(E + 3);
            araddr  = A_COUNT;
            arvalid = 1'b1;
            rready  = 1'b0;
            @(posedge clk); #1;
            arvalid = 1'b0;
            check(cur_rvalid == 1'b1, "read pending before reset");
            aresetn = 1'b0;
            @(posedge clk); #1;
            aresetn = 1'b1;
            check(cur_rvalid == 1'b0, "rvalid low after reset");
            check(cur_irq == 1'b0, "irq low after reset");
            check(cur_arready == 1'b1 && cur_awready == 1'b1 && cur_wready == 1'b1, "readies high after reset");
            rd(A_CTRL,   32'h0, OKAY);
            rd(A_LOAD,   32'h0, OKAY);
            rd(A_COUNT,  32'h0, OKAY);
            rd(A_STATUS, 32'h0, OKAY);
            wait_until(cyc + 10);
            rd(A_COUNT,  32'h0, OKAY);
            rd(A_STATUS, 32'h0, OKAY);
            check(cur_irq == 1'b0, "irq stays low after reset");
        end
    endtask

    // ------------------------------------------------------------------
    // Main
    // ------------------------------------------------------------------
    initial begin
        passed  = 0;
        failed  = 0;
        cyc     = 0;
        nonce   = 0;
        ctx     = "init";
        sel     = 1'b0;
        awaddr  = 8'h0;
        araddr  = 8'h0;
        wdata   = 32'h0;
        wstrb   = 4'h0;
        awvalid = 1'b0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        arvalid = 1'b0;
        rready  = 1'b0;
        aresetn = 1'b0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        repeat (4) @(posedge clk);
        #1;
        aresetn = 1'b1;

        sel = 1'b0;
        run_suite;

        aresetn = 1'b0;
        @(posedge clk); #1;
        aresetn = 1'b1;
        sel = 1'b1;
        run_suite;

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog
    initial begin
        #5000000;
        failed = failed + 1;
        $error("watchdog timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
